const EQEmuConfig* Config=nullptr;
using namespace Housing;
namespace {
void Require(bool b,const char* why){if(!b)throw std::runtime_error(why);}
auto Q(Database&d,const std::string&q){auto r=d.QueryDatabase(q,false);Require(r.Success(),"Housing installation query failed");return r;}
std::string Quote(Database&d,const std::string&s){return "'"+d.Escape(s)+"'";}
std::string Hash(const std::string&s){unsigned char out[32];SHA256(reinterpret_cast<const unsigned char*>(s.data()),s.size(),out);std::string h;for(auto c:out){h+="0123456789abcdef"[c>>4];h+="0123456789abcdef"[c&15];}return h;}
std::string Hex(const std::vector<uint8_t>&b){std::string s;for(auto c:b){s+="0123456789abcdef"[c>>4];s+="0123456789abcdef"[c&15];}return s;}
uint32_t U(const Json::Value&v){Require(v.isUInt(),"Expected unsigned content field");return v.asUInt();}
Json::Value Read(const char*path,std::string&raw){std::ifstream f(path,std::ios::binary);Require(bool(f),"Generated content proposal missing");raw.assign(std::istreambuf_iterator<char>(f),{});Require(raw.size()<=4*1024*1024,"Content proposal too large");Json::CharReaderBuilder b;b["rejectDupKeys"]=true;b["failIfExtra"]=true;Json::Value v;std::istringstream text(raw);std::string error;Require(Json::parseFromStream(b,text,&v,&error)&&v.isObject(),"Invalid content JSON");Require(v["format"].asString()=="housing-fresh-variant-catalogue-v1"&&!v["authentic_live_catalogue"].asBool(),"Unrecognized reconstructed content proposal");return v;}
EstateWire::Definition Definition(const Json::Value&j){EstateWire::Definition d;d.id=U(j["id"]);d.type=U(j["type"]);d.zone_id=U(j["zone_id"]);for(auto [key,p]:std::initializer_list<std::pair<const char*,uint32_t*>>{{"area_id",&d.area_id},{"group_id",&d.group_id},{"dynamic_zone_id",&d.dynamic_zone_id},{"icon",&d.icon},{"max_items",&d.max_items},{"max_non_estate_items",&d.max_non_estate_items},{"max_npc_items",&d.max_npc_items},{"max_children",&d.max_children},{"purchase_scheme",&d.purchase_scheme},{"upkeep_scheme",&d.upkeep_scheme}})if(j.isMember(key))*p=U(j[key]);if(j.isMember("address"))d.address=j["address"].asString();for(auto&c:j["children"])d.children.push_back(U(c));if(j.isMember("switch_coordinates")){Require(j["switch_coordinates"].size()==3,"Invalid switch coordinates");for(unsigned n=0;n<3;++n)d.switch_coordinates[n]=j["switch_coordinates"][n].asFloat();}if(j.isMember("switch_heading"))d.switch_heading=j["switch_heading"].asFloat();return d;}
Catalog::Bundle Content(const Json::Value&j){Catalog::Bundle b;for(const char*field:{"house_definitions","child_estate_definitions"}){Require(j[field].isArray(),"Content definitions missing");for(auto&d:j[field])b.definitions.push_back(Definition(d));}return b;}
std::unique_ptr<Database> Connect(){const auto*c=EQEmuConfig::get();Require(c,"Server configuration unavailable");auto d=std::make_unique<Database>();Require(d->Connect(c->DatabaseHost,c->DatabaseUsername,c->DatabasePassword,c->DatabaseDB,c->DatabasePort,"housing-content-install"),"Database connection failed");return d;}
template<class T>T Value(Result<T>r){Require(bool(r),"Production housing allocator/import refused content");return std::move(r.value);}
void Stopped(){Housing::OfflineProcessGuard::RequireWorldAndZoneStopped();}
Json::Value Describe(const Catalog::Bundle&b,const std::string&hash){Json::Value j;j["schema"]="housing-content-install-result-v1";j["catalog_key"]=b.key;j["source_sha256"]=hash;j["original_live_catalogue"]=false;j["personal_plots"]=71;j["guild_plots"]=4;j["fake_player_ownership_created"]=false;j["guild_exterior_limits_policy"]="200 items / 6 NPCs; labelled server default";j["guild_minimum_members_policy"]=1;j["inferred_103_betwixt_address"]=true;j["local_vertical_policy"]="collision minimum minus10 to maximum plus200";j["definition_count"]=Json::UInt(b.definitions.size());j["region_count"]=Json::UInt(b.regions.size());return j;}
std::string FileHash(const std::filesystem::path&path){std::ifstream f(path,std::ios::binary);Require(bool(f),"Original private runtime resource missing");SHA256_CTX state;SHA256_Init(&state);char chunk[65536];while(f.read(chunk,sizeof chunk)||f.gcount())SHA256_Update(&state,chunk,size_t(f.gcount()));Require(!f.bad(),"Private resource read failed");unsigned char out[32];SHA256_Final(out,&state);return Hex(std::vector<uint8_t>(out,out+32));}
void CrateConfiguration(Database&db,const Catalog::Export&e){
 if(std::filesystem::exists(".crate-test.json"))return; // Preserve legacy placed-crate manifest identity.
 if(std::filesystem::exists("housing-crate-content.json")){std::ifstream f("housing-crate-content.json");std::string raw{std::istreambuf_iterator<char>(f),{}};Require(bool(CrateContentManifest::Parse(raw)),"Existing production crate manifest is invalid");return;}
 Require(FileHash("housing-test-assets/furniture06.eqg")==CrateGeometry::Original.archive_sha256,"Original crate archive mismatch");const auto map=FileHash("maps/base/neighborhood.map");Require(map=="d16b27d7c3a07797a45b2900017652d58875207122e7df9e0a506b270d5b6f14","Reviewed Sunrise collision map mismatch");auto rows=Q(db,"SELECT idfile,UNK224,UNK227,UNK228,UNK229 FROM items WHERE id=62586");Require(rows.RowCount()==1,"Original moving crate item absent");auto r=rows.begin();for(unsigned k=0;k<5;++k)Require(r[k],"Moving crate physical metadata missing");Require(std::string(r[0])=="IT20028"&&std::string(r[1])=="142"&&std::string(r[2])=="174","Moving crate original metadata mismatch");Json::Value j;j["schema"]="housing-crate-content-v1";j["version"]=1;j["item_template_id"]=62586;j["definition_id"]=174;j["client_sha256"]=HouseGeometry::ClientSha256;j["renderer_sha256"]=HouseGeometry::RendererSha256;j["crate_archive_sha256"]=CrateGeometry::Original.archive_sha256;j["crate_member_sha256"]=CrateGeometry::Original.member_sha256;j["crate_witness_sha256"]=CrateGeometry::Original.witness_sha256;j["catalog_key"]=e.catalog.key;j["catalog_revision"]=Json::UInt64(e.catalog.revision);j["neighborhood_map_sha256"]=map;j["placement_mask"]=142;j["minimum_scale_bits"]=uint32_t(std::stoul(r[3]));j["maximum_scale_bits"]=uint32_t(std::stoul(r[4]));j["definitions_hex"]=Hex(e.definition_payload);j["regions_hex"]=Hex(e.region_payload);Json::StreamWriterBuilder writer;auto raw=Json::writeString(writer,j)+"\n";Require(bool(CrateContentManifest::Parse(raw)),"Generated production crate profile invalid");std::ofstream f("housing-crate-content.json",std::ios::binary);f<<raw;Require(bool(f),"Crate profile write failed");
}
void Write(const char*path,const Json::Value&v){std::ofstream f(path);Json::StreamWriterBuilder b;f<<Json::writeString(b,v)<<'\n';Require(bool(f),"Installation result could not be saved");}
}
int main(int argc,char**argv){try{Require(argc==7,"Usage: housing_install --plan|--apply proposal.json request-key name result.json --reconstructed-defaults");const std::string mode=argv[1],key=argv[3],name=argv[4];Require((mode=="--plan"||mode=="--apply")&&std::string(argv[6])=="--reconstructed-defaults","Explicit reconstructed-default policy required");Require(!key.empty()&&key.size()<=70,"Installation key length invalid");std::string raw;auto proposal=Read(argv[2],raw);const auto hash=Hash(raw);auto content=Content(proposal);SunriseNeighborhoodDefaults::Settings settings;settings.catalog_key="installed:"+key;settings.name=name;settings.source_sha256=hash;settings.neighborhood_id=1;settings.root_definition_id=1200000;settings.first_plot_definition_id=1200001;settings.first_region_id=1300001;settings.first_price_id=1400001;settings.guild_max_items=200;settings.guild_max_npc_items=6;settings.allow_inferred_103_betwixt=true;for(unsigned i=0;i<75;++i)settings.plot_ids[i]=i+1;auto pure=SunriseNeighborhoodDefaults::Build(settings,content);auto report=Describe(pure,hash);if(mode=="--plan"){report["read_only"]=true;Write(argv[5],report);std::cout<<"HOUSING_CONTENT_PLAN_PASS 75 plots, reviewed house/crate definitions, no database writes\n";return 0;}
Stopped();RegisterExecutablePlatform(ExePlatformClientImport);EQEmuLogSys::Instance()->LoadLogSettingsDefaults();Require(EQEmuConfig::LoadConfig("."),"Server configuration missing");auto db=Connect();Require(RuntimeActivation::AllowsReconstructedContent(*db),"Database reconstructed-content activation missing");auto receipt=Q(*db,"SELECT i.source_sha256,n.name FROM housing_content_installations i JOIN housing_neighborhoods n ON n.id=i.neighborhood_id WHERE i.catalog_key="+Quote(*db,settings.catalog_key));if(receipt.RowCount()){Require(receipt.RowCount()==1&&std::string(receipt.begin()[0])==hash&&receipt.begin()[1]&&std::string(receipt.begin()[1])==name,"Installed content source/name changed; use a new installation key");report["already_installed"]=true;Write(argv[5],report);std::cout<<"HOUSING_CONTENT_ALREADY_INSTALLED unchanged installation receipt\n";return 0;}
Require(!Q(*db,"SELECT character_id FROM housing_inventory_sessions WHERE active=1 LIMIT 1").RowCount(),"Active inventory sessions prevent installation");Require(!Q(*db,"SELECT character_id FROM housing_live_item_leases WHERE active=1 OR pending_key IS NOT NULL LIMIT 1").RowCount(),"Live inventory leases prevent installation");for(const char*table:{"housing_live_escrow_pending","housing_house_inventory_pending","housing_native_plot_purchase_pending"})Require(!Q(*db,"SELECT 1 FROM "+std::string(table)+" LIMIT 1").RowCount(),"Unresolved inventory application prevents installation");
PersistenceService persistence(Connect(),{true,100,32000});auto hood=Value(persistence.CreateNeighborhood("install:"+key,name,712,0));settings.neighborhood_id=hood.id;size_t i=0;for(const auto&p:SunrisePlotReconstruction::PersonalPlots)settings.plot_ids[i++]=Value(persistence.DefinePlot(hood.id,p.marker_id,std::string(p.address))).id;for(const auto&p:SunrisePlotReconstruction::GuildPlots)settings.plot_ids[i]=Value(persistence.DefinePlot(hood.id,199+uint32_t(i-71),std::string(p.address))).id,++i;auto bundle=SunriseNeighborhoodDefaults::Build(settings,content);Catalog::Service catalogs(Connect(),{true});auto current=catalogs.Load(bundle.key);Catalog::Export exported;if(current){Require(current.value.catalog.provenance.sha256==hash&&current.value.catalog.revision==1&&current.value.definition_payload==EstateWire::EncodeBootstrap(bundle.definitions,bundle.costs)&&current.value.region_payload==RegionWire::EncodeBootstrap(bundle.regions),"Existing unsealed installation content differs");exported=std::move(current.value);}else{Require(current.error==Error::NotFound,"Existing catalogue lookup failed");exported=Value(catalogs.Import(bundle,0));}
CrateConfiguration(*db,exported);
Q(*db,"START TRANSACTION");try{const auto catalog=Quote(*db,bundle.key),defs=Quote(*db,Hash(std::string(exported.definition_payload.begin(),exported.definition_payload.end()))),regions=Quote(*db,Hash(std::string(exported.region_payload.begin(),exported.region_payload.end())));for(const auto&d:bundle.definitions)if(d.type==4||d.type==8){const auto id=std::to_string(d.id);Q(*db,"INSERT INTO housing_native_plot_purchase_policies(catalog_key,definition_id,catalog_revision,definitions_sha256,regions_sha256,policy_revision,allow_carried_copper,max_owned_plots,enabled,review_source,allow_guild_zero_copper,reviewed_minimum_guild_members,allow_guild_carried_copper) VALUES("+catalog+","+id+",1,"+defs+","+regions+",1,1,"+(d.type==8?"1":"3")+",1,'Portable reconstructed Sunrise defaults; original2013 values unknown',0,"+(d.type==8?"1":"0")+","+(d.type==8?"1":"0")+")");Q(*db,"INSERT INTO housing_upkeep_enrollment_policy(catalog_key,definition_id,catalog_revision,definitions_sha256,regions_sha256,mode,review_reference,allow_bulk_carried_copper) VALUES("+catalog+","+id+",1,"+defs+","+regions+",1,'Portable reconstructed copper rent; current catalogue generation',1)");}Q(*db,"INSERT INTO housing_content_installations(catalog_key,source_sha256,neighborhood_id) VALUES("+catalog+","+Quote(*db,hash)+","+std::to_string(hood.id)+")");Q(*db,"COMMIT");}catch(...){db->QueryDatabase(std::string("ROLLBACK"),false);throw;}
report["applied"]=true;report["neighborhood_id"]=hood.id;report["instance_id"]=hood.instance_id;report["catalog_revision"]=Json::UInt64(exported.catalog.revision);Write(argv[5],report);std::cout<<"HOUSING_CONTENT_INSTALL_PASS 75 available plots, purchase and upkeep policies; no fake owners\n";return 0;
}catch(const std::exception&e){std::cerr<<"HOUSING_CONTENT_INSTALL_REFUSED "<<e.what()<<'\n';return 1;}}
